<script setup>
import {ref,computed,onMounted} from 'vue'
import {api,post} from '../api'
const tab=ref('今日'),today=ref(null),reminders=ref([]),members=ref([]),medicines=ref([]),error=ref(''),notice=ref(''),busy=ref(false),memberId=ref(''),medicineId=ref(''),time=ref('08:00'),dose=ref(''),meal=ref('餐后'),start=ref(''),end=ref(''),history=ref([]),recordedBy=ref(''),temperature=ref(''),note=ref('')
const actualTime=ref('')
function localTimeInput(){
  const now=new Date()
  return new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16)
}
const member=computed(()=>members.value.find(m=>m.id===memberId.value))
const available=computed(()=>medicines.value.filter(m=>m.owner===member.value?.name))
const medicine=computed(()=>available.value.find(m=>m.id===medicineId.value))
async function load(){try{[today.value,reminders.value,members.value,medicines.value]=await Promise.all([api('/today'),api('/reminders?include_inactive=true'),api('/members'),api('/medicines')])}catch(e){error.value=e.message}}
function changeMember(){medicineId.value='';dose.value=''}
async function confirmDose(item){busy.value=true;error.value='';try{if(item.record_id){if(!confirm(`撤销“${item.member_name} · ${item.medicine_name}”的服药确认？`))return;await api(`/records/${item.record_id}`,{method:'DELETE'})}else{await post('/records',{reminder_id:item.reminder_id,medicine_id:item.medicine_id,member_id:members.value.find(m=>m.name===item.member_name)?.id,medicine_name:item.medicine_name,member_name:item.member_name,dose:item.dose})}await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function createReminder(){if(!medicine.value||!member.value)return;busy.value=true;error.value='';try{await post('/reminders',{medicine_id:medicine.value.id,medicine_name:medicine.value.name,member_name:member.value.name,time:time.value,dose:dose.value,meal_label:meal.value});notice.value='提醒已保存';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function toggleReminder(r){try{await api('/reminders/'+r.id,{method:'PATCH',body:JSON.stringify({is_active:!r.is_active})});await load()}catch(e){error.value=e.message}}
async function remove(r){if(!confirm(`删除“${r.member_name} · ${r.medicine_name} · ${r.time}”提醒？历史保留。`))return;try{await api('/reminders/'+r.id,{method:'DELETE'});await load()}catch(e){error.value=e.message}}
async function query(){error.value='';try{const q=new URLSearchParams();if(memberId.value)q.set('member_id',memberId.value);if(medicineId.value)q.set('medicine_id',medicineId.value);if(start.value)q.set('start_date',start.value);if(end.value)q.set('end_date',end.value);history.value=await api('/records?'+q)}catch(e){error.value=e.message}}
async function childRecord(){if(!medicine.value||!member.value||!actualTime.value)return;busy.value=true;error.value='';try{await post('/records',{medicine_id:medicine.value.id,member_id:member.value.id,medicine_name:medicine.value.name,member_name:member.value.name,dose:dose.value,recorded_by:recordedBy.value,temperature:String(temperature.value),note:note.value,taken_at:new Date(actualTime.value).toISOString()});notice.value='已按实际服药时间保存喂药记录';actualTime.value='';recordedBy.value='';temperature.value='';note.value='';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="chips"><button class="chip" :class="{active:tab===name}" v-for="name in ['今日','提醒设置','历史记录','儿童记录']" :key="name" @click="tab=name;error='';notice=''">{{name}}</button></div><p class="error" v-if="error">{{error}}</p><p class="feedback" v-if="notice">{{notice}}</p><template v-if="tab==='今日'"><section class="panel" v-if="today"><h2>{{today.date}} · 完成 {{today.completed}} / {{today.total}}</h2><p class="empty" v-if="!today.items.length">暂无提醒，请先在提醒设置中添加。</p><div class="record" v-for="item in today.items" :key="item.reminder_id"><div><b>{{item.time}} · {{item.medicine_name}}</b><p>{{item.member_name}} · {{item.dose}} · {{item.meal_label}}</p></div><button :disabled="busy" @click="confirmDose(item)">{{item.record_id?'已服药 · 撤销':'确认服药'}}</button></div></section></template><template v-else><section class="panel"><label>家庭成员<select v-model="memberId" @change="changeMember"><option value="">请选择成员</option><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>具体药品<select v-model="medicineId" @change="dose=medicine?.dose||''"><option value="">{{tab==='历史记录'?'全部药品':'请选择药品'}}</option><option v-for="m in available" :key="m.id" :value="m.id">{{m.name}}</option></select></label><form v-if="tab==='提醒设置'" @submit.prevent="createReminder"><div class="form-grid"><label>提醒时间<input type="time" v-model="time" required></label><label>一次剂量<input v-model="dose" required></label><label>服用时段<select v-model="meal"><option>餐前</option><option>餐后</option><option>随餐</option><option>遵医嘱</option></select></label></div><button class="primary" :disabled="busy||!medicineId||!memberId">保存提醒</button></form><template v-else-if="tab==='历史记录'"><div class="form-grid"><label>开始日期<input type="date" v-model="start"></label><label>结束日期<input type="date" v-model="end"></label></div><button @click="query">查询记录</button></template><form v-else @submit.prevent="childRecord"><label>本次剂量<input v-model="dose" required></label><label>记录人<input v-model="recordedBy" required></label><label>体温（℃，可选）<input v-model="temperature" type="number" min="30" max="45" step="0.1"></label><label>备注<textarea v-model="note"></textarea></label><label>儿童实际服药时间<input v-model="actualTime" type="datetime-local" :max="localTimeInput()" required></label><button class="primary" :disabled="busy||!memberId||!medicineId">保存儿童喂药记录</button></form></section><section class="panel" v-if="tab==='提醒设置'"><h2>全部提醒</h2><article v-for="r in reminders" :key="r.id"><b>{{r.member_name}} · {{r.medicine_name}}</b><p>{{r.time}} · {{r.dose}} · {{r.is_active?'已启用':'已停用'}}</p><button @click="toggleReminder(r)">{{r.is_active?'停用':'启用'}}</button><button @click="remove(r)">删除</button></article></section><section class="panel" v-else-if="tab==='历史记录'"><p class="empty" v-if="!history.length">暂无查询结果，请选择条件后查询。</p><article v-for="r in history" :key="r.id"><b>{{r.member_name}} · {{r.medicine_name}}</b><p>{{new Date(r.taken_at).toLocaleString('zh-CN')}} · {{r.dose}}</p><p v-if="r.recorded_by">记录人：{{r.recorded_by}} · 体温：{{r.temperature ? r.temperature+'℃' : '未填写'}}</p><p>{{r.note}}</p></article></section></template></template>
